const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let S={data:null,page:'home',project:null,importPreview:null,expenseImportPreview:null,search:'',homeStatus:'active'};
const budgetDataChannel='project-finance-budget-data-v1';
const systemRuntime={ready:false,stopped:false,healthTimer:0,healthFailures:0,nativeFetch:window.fetch.bind(window)};
function setSystemGuard(state,title,message,secondary=''){const guard=$('#systemGuard');if(!guard)return;guard.dataset.state=state;guard.hidden=false;const card=guard.querySelector('.system-guard-card');card.innerHTML=`<div class="system-guard-spinner" aria-hidden="true"></div><h1 id="systemGuardTitle">${esc(title)}</h1><p id="systemGuardMessage">${esc(message)}</p>${secondary?`<p class="system-guard-secondary">${esc(secondary)}</p>`:''}`;document.body.setAttribute('aria-busy','true')}
function showSystemStopped(startup=false){if(systemRuntime.stopped)return;systemRuntime.stopped=true;systemRuntime.ready=false;if(systemRuntime.healthTimer)clearInterval(systemRuntime.healthTimer);setSystemGuard('stopped',startup?'無法連接經費管理程式':'經費管理程式已停止回應','請關閉目前分頁，重新執行「啟動經費管理.bat」。','關閉分頁後，尚未儲存的表單資料將無法保留。若中斷前剛按下儲存，重新啟動後請先檢查紀錄是否已建立，避免重複新增。')}
function showSystemLoadFailure(){if(systemRuntime.stopped)return;systemRuntime.stopped=true;setSystemGuard('stopped','經費管理資料載入失敗','請關閉目前分頁，重新執行「啟動經費管理.bat」。','如果再次發生，請記下錯誤畫面並回報。')}
function isLocalApiRequest(input){try{const raw=typeof input==='string'?input:input?.url||'';const u=new URL(raw,location.href);return u.origin===location.origin&&u.pathname.startsWith('/api/')}catch{return false}}
window.fetch=async function(input,init){try{return await systemRuntime.nativeFetch(input,init)}catch(error){if(systemRuntime.ready&&!systemRuntime.stopped&&error?.name!=='AbortError'&&isLocalApiRequest(input))showSystemStopped();throw error}};
const wait=(ms)=>new Promise(resolve=>setTimeout(resolve,ms));
async function waitForLocalServer(timeoutMs=20000){const until=Date.now()+timeoutMs;while(Date.now()<until){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),1200);try{const response=await systemRuntime.nativeFetch(`/api/health?check=${Date.now()}`,{cache:'no-store',signal:controller.signal});if(response.ok)return true}catch{}finally{clearTimeout(timer)}await wait(450)}return false}
function startHealthMonitor(){if(systemRuntime.healthTimer)clearInterval(systemRuntime.healthTimer);systemRuntime.healthFailures=0;systemRuntime.healthTimer=setInterval(async()=>{if(!systemRuntime.ready||systemRuntime.stopped)return;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),1400);try{const response=await systemRuntime.nativeFetch(`/api/health?check=${Date.now()}`,{cache:'no-store',signal:controller.signal});if(!response.ok)throw Error('Health check failed');systemRuntime.healthFailures=0}catch{systemRuntime.healthFailures++;if(systemRuntime.healthFailures>=2)showSystemStopped()}finally{clearTimeout(timer)}},2500)}
async function startApp(){setSystemGuard('loading','正在載入經費管理資料','請稍候，載入完成後會自動進入系統。');if(!await waitForLocalServer()){showSystemStopped(true);return}try{await load();if(!S.data||!Array.isArray(S.data.projects))throw Error('載入資料格式不正確');systemRuntime.ready=true;const guard=$('#systemGuard');if(guard)guard.hidden=true;document.body.removeAttribute('aria-busy');startHealthMonitor()}catch{showSystemLoadFailure()}}
if(localStorage.getItem('tablePageSizeVersion')!=='3'){localStorage.setItem('tablePageSize','5');localStorage.setItem('tablePageSizeVersion','3')}
const money=n=>new Intl.NumberFormat('zh-TW',{minimumFractionDigits:0,maximumFractionDigits:2}).format(Number(n||0));
const numericMoney=x=>Number(String(x?.value??x??0).replaceAll(',','')||0);
