const expenses=()=>S.data?.expenses.filter(x=>x.project_id==S.project)||[];
function isPendingExpense(x){const valid=v=>/^\d{4}-\d{2}-\d{2}$/.test(String(v||''));return !x.voided&&(!valid(x.submitted_date)||!valid(x.voucher_date)||x.submitted_date>localToday())}
function budgetExpenseSplit(item,rows=expenses()){const related=rows.filter(x=>Number(x.budget_item_id)===Number(item.id)&&!x.voided);return{confirmed:related.filter(x=>!isPendingExpense(x)).reduce((sum,x)=>sum+Number(x.amount||0),0),pending:related.filter(isPendingExpense).reduce((sum,x)=>sum+Number(x.amount||0),0)}}
function balanceNotes(){return '<p class="hint balance-notes">帳面餘額：流用後預算扣除已核銷與待核銷後的金額，不考慮規劃中流用。可用餘額：帳面餘額再扣除規劃中流用已保留的金額，代表目前實際還能核銷或流出的金額。</p>'}
