let toastTimer=0;
function toast(s){const t=$('#toast');t.innerHTML=`<span>${esc(s)}</span><button type="button" aria-label="關閉提示" onclick="this.parentElement.classList.remove('show')">×</button>`;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),8000);const form=$('#modalRoot form');if(form&&!String(s).startsWith('已')){let error=$('#modalSaveError');if(!error){error=document.createElement('div');error.id='modalSaveError';error.className='note warn';error.setAttribute('role','alert');form.insertAdjacentElement('afterend',error);const clear=()=>{error.hidden=true};form.addEventListener('input',clear);form.addEventListener('change',clear)}error.textContent=s;error.hidden=false}}
function fmtRatio(n){return n==null?'—':(Math.round(Math.abs(n)*1000+1e-9)/10).toFixed(1)+'%'}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">PROJECT FINANCE</div><h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${actions}</div></div>`}
function tableAlignmentPreset(page){const center={選取:'center','🔒':'center',操作:'center'},text={經費類別:'left',經費屬性:'left',預算科目:'left',單位:'left',備註:'left',批次說明:'left'},moneyColumns={初始預算:'right',流入:'right',流出:'right',流用後預算:'right',已核銷:'right',待核銷:'right',帳面餘額:'right',可用餘額:'right',金額:'right',流用金額:'right',核銷金額:'right'};const presets={home:{專案名稱:'left',執行起日:'center',執行迄日:'center',真實執行率:'center',預估執行率:'center'},budget:{...text,...moneyColumns},expenses:{...text,...moneyColumns,登錄日期:'center',憑證日期:'center',刪除時間:'center','原核銷 ID':'center','經費類別／單位／屬性／科目':'left',付款對象分配:'left',刪除前狀態:'left','批次 ID／說明':'left'},transfers:{...text,...moneyColumns,流用日期:'center','流出單位／預算科目':'left','流入單位／預算科目':'left'},application:{...text,變更前預算:'right',變更後預算:'right',增減:'right'},options:{...text},email:{類型:'left','姓名／稱呼':'left',Email:'left',所屬單位:'left',寄送時間:'left',收件人:'left',結果:'left'}};return {...center,...(presets[page]||{})}}
function table(headers,rows,opts={}){const key=opts.key||`${S.page}:${headers.join('|')}`;const pageName=({home:'所有專案',overview:'專案總覽',budget:'專案經費',expenses:'核銷紀錄',transfers:'經費流用',estimate:'補充保費估算',application:'流用科目變更',email:'Email 經費報告',options:'選項資料'})[S.page]||'資料';const fieldNames=headers.filter(h=>h&&h!=='選取'&&h!=='操作').slice(0,3);const caption=opts.caption||pageName+'資料表'+(fieldNames.length?'，主要欄位為'+fieldNames.join('、'):'');return `<div class="table-component" data-table-key="${esc(key)}" data-align="${esc(JSON.stringify({...tableAlignmentPreset(S.page),...(opts.align||{})}))}" data-table-mode="${opts.mode||(opts.pageSize?"overview":"standard")}" data-page-size="${opts.pageSize||''}" data-no-page="${opts.noPage?'1':''}" data-scroll-table="${opts.scroll?'1':''}" data-no-align="${opts.noAlign?'1':'0'}" data-narrow-fit="${opts.narrowFit||0}"><div class="table-wrap"><table class="table" style="--col-count:${headers.length}"><caption class="visually-hidden">${esc(caption)}</caption><thead><tr>${headers.map((h,i)=>`<th scope="col" class="${h==='操作'||(!h&&i===headers.length-1)?'action-col':''} ${h==='選取'?'select-col':h==='🔒'?'lock-col':''} ${opts.narrowHide?.includes(h)?'col-narrow-hide':''}" ${h==='選取'?'data-column-label="選取"':''}>${h==='選取'&&opts.selectAll?`<input type="checkbox" aria-label="全選本頁" onchange="toggleVisibleChecks(this,'${opts.selectAll}')">`:h&&h!=='操作'&&h!=='選取'&&h!=='🔒'&&S.page!=='budget'&&opts.sort!==false?`<button type="button" class="sort-button" aria-label="依${esc(h)}排序">${h}<span class="sort-indicator">↕</span></button>`:h}</th>`).join('')}</tr></thead><tbody>${rows||''}</tbody></table></div><div class="table-pagination"></div></div>`}
function tabCount(value){const count=Number(value)||0;return `<span class="tab-count" aria-label="${count} 筆" title="${count} 筆">${count>999?'999+':count}</span>`}
