function planStatus(p,now=localToday()){if(p.end_date&&now>p.end_date)return 'done';if(p.start_date&&now<p.start_date)return 'future';return 'active'}
function localToday(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function addCalendarMonths(date,months){const d=new Date(`${date}T12:00:00`),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+months);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function viewHome(){
 const all=S.data.projects||[],status=S.homeStatus||'active',todayDate=localToday(),cutoff=addCalendarMonths(todayDate,3),counts={active:0,future:0,done:0,all:all.length};
 all.forEach(p=>counts[planStatus(p,todayDate)]++);
 const plans=all.filter(p=>status==='all'||planStatus(p,todayDate)===status).sort((a,b)=>{const as=planStatus(a,todayDate),bs=planStatus(b,todayDate),rank={active:0,future:1,done:2};if(status==='all'&&rank[as]!==rank[bs])return rank[as]-rank[bs];return (a.end_date||'9999-12-31').localeCompare(b.end_date||'9999-12-31')||a.name.localeCompare(b.name,'zh-Hant')});
 const rows=plans.map(p=>{const e=S.data.expenses.filter(x=>x.project_id==p.id&&!x.voided),confirmed=e.filter(x=>!isPendingExpense(x)).reduce((sum,x)=>sum+Number(x.amount||0),0),forecast=e.reduce((sum,x)=>sum+Number(x.amount||0),0),denominator=Number(p.total_budget||0),realRate=denominator>0?confirmed/denominator:null,forecastRate=denominator>0?forecast/denominator:null,soon=planStatus(p,todayDate)!=='done'&&p.end_date&&p.end_date>=todayDate&&p.end_date<=cutoff;return `<tr><td>${soon?'<span class="deadline-badge" title="專案將於三個月內到期" aria-label="專案將於三個月內到期">⏱️</span> ':''}<b>${esc(p.name)}</b><div class="muted">${esc(p.code)}</div></td><td>${esc(showDate(p.start_date))}</td><td>${esc(showDate(p.end_date))}</td><td class="percent">${fmtRatio(realRate)}</td><td class="percent">${fmtRatio(forecastRate)}</td><td class="action-col"><button class="smallbtn" type="button" onclick="browseProject(${p.id})">瀏覽</button></td></tr>`}).join('');
 return `${pageHead('所有專案','真實執行率＝已核銷 ÷ 專案經費總額；預估執行率＝含待核銷金額 ÷ 專案經費總額。⏱️ 表示三個月內到期。',`<button class="primary" onclick="projectModal()">＋ 新增專案</button>`)}<div class="panel"><div class="home-toolbar-row"><div class="toolbar status-tabs">${[['active','執行中'],['future','未執行'],['done','已完成'],['all','總覽']].map(([k,label])=>`<button class="status-tab ${status===k?'active':''}" onclick="S.homeStatus='${k}';render()">${label} ${tabCount(counts[k])}</button>`).join('')}</div><div class="toolbar home-export"><label>匯出狀態 <select id="homeExportStatus"><option value="active" ${status==='active'?'selected':''}>執行中</option><option value="future" ${status==='future'?'selected':''}>未執行</option><option value="done" ${status==='done'?'selected':''}>已完成</option><option value="all" ${status==='all'?'selected':''}>總覽</option></select></label><label>格式 <select id="homeExportFormat"><option value="xlsx">Excel</option><option value="md">Markdown</option><option value="pdf">PDF</option></select></label><button class="secondary" type="button" onclick="exportProjects()">匯出專案</button></div></div>${table(['專案名稱','執行起日','執行迄日','真實執行率','預估執行率','操作'],rows||'<tr><td colspan="6" class="empty">此狀態沒有專案</td></tr>',{key:'home:projects'})}</div>`
}
async function exportProjects(){const status=$('#homeExportStatus').value,format=$('#homeExportFormat').value,pdfWindow=format==='pdf'?window.open('about:blank','_blank'):null;if(format==='pdf'&&!pdfWindow){toast('瀏覽器封鎖了報表預覽，請允許此網站開啟視窗');return}try{const r=await fetch(`/api/export-projects?status=${encodeURIComponent(status)}&format=${encodeURIComponent(format)}`);if(!r.ok){const e=await r.json();throw Error(e.error||'匯出失敗')}const blob=await r.blob();if(format==='pdf'){pdfWindow.location.replace(URL.createObjectURL(blob));return}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`所有專案_${{active:'執行中',future:'未執行',done:'已完成',all:'總覽'}[status]}.${format==='md'?'md':'xlsx'}`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){pdfWindow?.close();toast(e.message)}}
function columnLabel(th){const sort=th.querySelector('.sort-button');return th.dataset.columnLabel||(sort?sort.childNodes[0].textContent.trim():th.textContent.trim())}
function defaultAlignment(label,key=''){if(/^(選取|🔒|操作)$/.test(label))return 'center';if(key==='home:projects')return label==='專案名稱'?'left':'center';if(key.startsWith('overview:')){if(/執行率/.test(label))return 'center';if(/預算|核銷|餘額/.test(label))return 'right';return 'left'}if(label==='原核銷 ID'||label==='列次')return 'center';if(S.page!=='email'&&/日期|刪除時間/.test(label))return 'center';if(/^(經費類別|經費屬性|預算科目|單位|批次說明|備註|納入科目)$/.test(label)||/單位／預算科目|經費類別／單位／屬性／科目|付款對象分配|批次 ID／說明|刪除前狀態/.test(label))return 'left';if(/執行率|百分比|比率/.test(label))return 'center';if(/預算|金額|餘額|逐筆保費|差額|流入|流出|核銷/.test(label))return 'right';return 'left'}
