function viewApplication(){let report=S.flowReport,from=report?.date_from||localToday(),to=report&&report.date_to!==report.date_from?report.date_to:'';let rows=report?.rows||[];return `${pageHead('流用科目變更','依流用日期彙總科目預算變更前後金額，不需手動輸入。',report?``:'')}<div class="panel report-filters"><form id="flowReportForm" class="toolbar">${field('起日','report_start',from,'','date')}${field('迄日','report_end',to,'','date')}<button type="button" class="primary" onclick="loadFlowChanges()">查詢</button></form><div class="hint">只填一個日期即查該日；填起訖日期則合併區間內所有有效流用。變更前為起始日前的預算，變更後為結束日流用完成後的預算。</div></div>${report?`<div class="panel"><div class="panel-title"><div><h2>${esc(showDate(report.date_from))}${report.date_to!==report.date_from?' 至 '+esc(showDate(report.date_to)):''} 流用科目變更</h2><p>只列出預算總額有變動的科目；按經費類別及經費屬性分類，合併各單位金額。</p></div><button type="button" class="secondary flow-export" data-action="export-flow-changes">匯出此次查詢（Excel）</button></div>${table(['經費類別','經費屬性','預算科目','變更前預算','變更後預算','增減'],rows.map(x=>`<tr><td>${esc(x.source)}</td><td>${esc(x.category)}</td><td>${esc(x.subject)}</td><td class="num">${money(x.before)}</td><td class="num">${money(x.after)}</td><td class="num ${x.change<0?'negative':'positive'}">${x.change>0?'+':''}${money(x.change)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">選取期間內沒有科目總額變更</td></tr>')}</div>`:''}`}


function viewExport(){let owners=optList('owner');return `${pageHead('匯出資料','集中輸出專案彙總與各單位的經費、核銷及流用紀錄。')}<div class="panel"><div class="panel-title"><div><h2>匯出內容與格式</h2><p>選擇資料範圍、報表類型、檔案格式及輸出方式。</p></div></div><div class="export-section"><h3>匯出內容</h3><div class="field"><label>資料範圍 <span class="field-mark required">必填</span></label><select id="exportScope" onchange="toggleExportOwners()"><option value="overall">專案彙總：專案經費總表、核銷與流用</option><option value="owners">所選單位：經費與核銷紀錄</option><option value="all">專案彙總＋所選單位（分工作表）</option></select></div><div id="exportOwnerOptions" class="field export-spaced-field" style="display:none"><label>單位 <span class="field-mark required">選填；匯出單位資料時必填</span></label><button type="button" id="toggleAllOwners" class="secondary" onclick="toggleAllExportOwners()">全選單位</button><div id="exportOwners" class="checkbox-list">${owners.map(o=>`<label><input type="checkbox" value="${esc(o)}">${esc(o)}</label>`).join('')}</div><div class="hint">勾選要匯出的單位，可複選。</div></div><p class="hint">專案彙總包含專案經費總表、核銷彙總與流用紀錄；所選單位資料包含經費總表、核銷明細與流用紀錄。</p></div><hr class="divider"><div class="export-section"><h3>格式與檔案方式</h3><div class="field"><label>報表類型 <span class="field-mark required">每次預設一般報表</span></label><select id="exportReportType"><option value="general" selected>一般報表</option><option value="reconciliation">對帳報表</option></select><p class="hint">對帳報表只列已核銷與已流用資料，不含待核銷及規劃中；此選擇不會提供給 Email。</p></div><div class="field"><label>檔案格式 <span class="field-mark required">必填</span></label><select id="exportFormat" onchange="toggleExportMode()"><option value="xlsx">Excel（.xlsx）</option><option value="md">Markdown（.md）</option><option value="pdf">PDF（系統產生預覽）</option></select></div><div id="exportModeBox" class="field export-spaced-field" style="display:none"><label>單位檔案方式 <span class="field-mark required">必填</span></label><select id="exportMode"><option value="combined">合併同一份檔案（每個單位各自工作表）</option><option value="separate">每個單位分開匯出（ZIP 壓縮檔）</option></select></div><div id="exportPdfOrientationBox" class="field export-spaced-field" style="display:none"><label>PDF 紙張方向 <span class="field-mark required">必填</span></label><select id="exportPdfOrientation"><option value="landscape">A4 橫式（預設）</option><option value="portrait">A4 直式</option></select></div><div class="note export-note">Excel 與 Markdown 可直接下載。PDF 會開啟系統產生的報表預覽，預設為 A4 橫式，可使用瀏覽器「另存為 PDF」。</div><button class="primary export-submit" onclick="runDataExport()">產生匯出檔案</button></div></div>`}
function toggleExportOwners(){let scope=$('#exportScope')?.value,box=$('#exportOwnerOptions');if(box)box.style.display=scope==='overall'?'none':'';toggleExportMode()}
function toggleAllExportOwners(){const host=$('#exportOwners'),button=$('#toggleAllOwners');if(!host||!button)return;const checks=[...host.querySelectorAll('input[type=checkbox]')],select=checks.some(x=>!x.checked);checks.forEach(x=>x.checked=select);button.textContent=select?'取消全選':'全選單位'}
function toggleExportMode(){let pdf=$('#exportFormat')?.value==='pdf',box=$('#exportModeBox'),orientation=$('#exportPdfOrientationBox');if(box)box.style.display=pdf||$('#exportScope')?.value!=='owners'?'none':'';if(orientation)orientation.style.display=pdf?'':'none'}

function expenseOwners(source){return source?optList('owner'):[]}
function expenseCategories(source,owner){return source&&owner?optList('category'):[]}
function expenseSubjects(source,owner,category=''){return source&&owner&&category?optList('subject'):[]}
