function confirmRestoreIssues(issues){return new Promise(resolve=>{const list=issues.map(x=>`<li>${esc(x.project_name)}：${esc(x.level)}「${esc(x.name)}」超出 ${money(x.excess)} 元</li>`).join('');modal('備份帳務問題',`<div class="note warn">此備份有 ${issues.length} 項帳務上限問題。仍要還原會以這份資料取代目前資料。</div><ul class="restore-issues">${list}</ul><div class="modal-confirm-actions"><button type="button" class="ghost" id="restoreIssuesCancel">取消</button><button type="button" class="danger" id="restoreIssuesProceed">仍要還原</button></div>`,null,{hideSave:true,wide:true});let settled=false;const observer=new MutationObserver(()=>{if(!$('#restoreIssuesCancel')&&!settled){settled=true;observer.disconnect();resolve(false)}});observer.observe($('#modalRoot'),{childList:true,subtree:true});const finish=choice=>{if(settled)return;settled=true;observer.disconnect();closeModal(true);resolve(choice)};$('#restoreIssuesCancel').onclick=()=>finish(false);$('#restoreIssuesProceed').onclick=()=>finish(true);$('#restoreIssuesCancel').focus()})}
