 const active=rows.filter(x=>!x.voided),pending=active.filter(isPendingExpense).length,total=active.reduce((n,x)=>n+Number(x.amount||0),0);
 const body=`<div class="hint">批次 #${id}　登錄日期：${esc(showDate(b.submitted_date))}　說明：${esc(b.description||'—')}<br>未作廢合計 ${money(total)} 元 · 待核銷 ${pending} 筆</div><div class="toolbar"><button type="button" class="secondary" onclick="batchModal(${id},true)">編輯批次</button><button type="button" class="danger" onclick="deleteBatches([${id}])">刪除批次</button><button type="button" class="primary" onclick="closeModal(true);expenseModal(null,${id},null,true)">＋ 在此批次新增明細</button></div>${table(['憑證日期','單位','預算科目','金額','狀態','備註','操作'],rows.map(x=>`<tr><td>${esc(showDate(x.voucher_date))}</td><td>${esc(x.owner)}</td><td>${esc(x.subject)}</td><td class="num">${money(x.amount)}</td><td>${x.voided?'<span class="muted">作廢</span>':isPendingExpense(x)?'<span class="badge pending">待核銷</span>':'已核銷'}</td><td>${esc(x.note||'')}</td><td class="action-col"><button type="button" class="smallbtn" onclick="closeModal(true);expenseModal(${x.id},${id},null,true)">編輯</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">此批次尚無明細</td></tr>')}`;
 modal(`核銷批次 #${id}`,body,null,{hideSave:true,wide:true})
