function setTheme(theme,persist=true){if(!['light','dark','custom'].includes(theme))theme='light';const root=document.documentElement;root.dataset.theme=theme;localStorage.setItem('budgetTheme',theme);const palette=S.data?.settings?.custom_theme||{};['canvas','paper','table-surface','table-head','ink','green','muted','line','primary-ink'].forEach(k=>root.style.removeProperty(`--${k}`));if(theme==='custom'&&palette.canvas){root.style.setProperty('--canvas',palette.canvas);root.style.setProperty('--paper',palette.paper);root.style.setProperty('--table-surface',palette.table||palette.paper);root.style.setProperty('--table-head',`color-mix(in srgb, ${palette.accent} 10%, ${palette.table||palette.paper})`);root.style.setProperty('--ink',palette.ink);root.style.setProperty('--green',palette.accent);root.style.setProperty('--muted',`color-mix(in srgb, ${palette.ink} 65%, ${palette.paper})`);root.style.setProperty('--line',`color-mix(in srgb, ${palette.ink} 18%, ${palette.paper})`);root.style.setProperty('--primary-ink',colorLuminance(palette.accent)>.45?'#111827':'#FFFFFF')}const names={light:'淺色',dark:'深色',custom:'自訂顏色'};$('#themeToggle').textContent=names[theme];if(persist)api({op:'theme_choice_save',theme}).catch(e=>toast(e.message))}
function readCustomPalette(){return Object.fromEntries(['canvas','paper','table','ink','accent'].map(k=>[k,$(`#palette_${k}`)?.value||'#FFFFFF']))}
function colorLuminance(hex){const rgb=hex.match(/[0-9a-f]{2}/gi).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2]}
function previewCustomTheme(){const p=readCustomPalette(),box=$('#customThemePreview'),note=$('#customThemeContrast');if(!box)return;box.style.background=p.canvas;box.style.color=p.ink;box.style.borderColor=`color-mix(in srgb, ${p.ink} 20%, ${p.paper})`;box.querySelector('.preview-surface').style.background=p.paper;box.querySelector('.preview-table').style.background=p.table;box.querySelector('.preview-action').style.background=p.accent;box.querySelector('.preview-action').style.color=colorLuminance(p.accent)>.45?'#111827':'#FFFFFF';const a=colorLuminance(p.ink),ratios=[p.paper,p.table,p.canvas].map(c=>{const b=colorLuminance(c);return (Math.max(a,b)+.05)/(Math.min(a,b)+.05)}),ratio=Math.min(...ratios);note.textContent=ratio<4.5?`文字與頁面、面板或表格底色的對比約 ${ratio.toFixed(1)}:1，可能不易閱讀。`:`文字與頁面、面板及表格底色的對比良好（最低約 ${ratio.toFixed(1)}:1）。`;note.className=ratio<4.5?'hint contrast-warning':'hint contrast-ok'}

