themeBgFile.onchange=async()=>{const file=themeBgFile.files?.[0];if(!file)return;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('圖片格式不支援，請使用 JPG、PNG 或 WebP。');if(file.size>15*1024*1024)throw Error('圖片檔案需小於 15 MB。');if(!window.createImageBitmap)throw Error('此瀏覽器無法讀取圖片，請改用 JPG、PNG 或 WebP。');const bitmap=await createImageBitmap(file);if(!bitmap.width||!bitmap.height){bitmap.close();throw Error('圖片內容無法解碼，請另存為 JPG、PNG 或 WebP 後再試。')}const scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');if(!ctx){bitmap.close();throw Error('無法處理此圖片。')}ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise((resolve,reject)=>canvas.toBlob(x=>x?resolve(x):reject(Error('圖片轉換失敗。')),'image/jpeg',.76));const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('讀取轉換後圖片失敗。'));reader.readAsDataURL(blob)});await api({op:'theme_background_save',data});applyThemeBackground(data);if(S.data)S.data.theme_background=data;$('#themeMenu').open=false;toast('主題背景已儲存至 SQLite')}catch(e){toast(e.message||'圖片無法解碼，請改用 JPG、PNG 或 WebP。')}finally{themeBgFile.value=''}};

