function budgetAllocationSummaryMarkup(){const p=proj();if(!p)return '';const total=Number(p.total_budget||0),allocated=budgets().reduce((s,x)=>s+Number(x.initial||0),0),remaining=total-allocated;return `<div class="allocation-summary"><div><span>專案總額</span><b>${money(total)} 元</b></div><div><span>已編列</span><b>${money(allocated)} 元</b></div><div class="${remaining<0?'negative':'unallocated'}"><span>尚未編列</span><b>${money(remaining)} 元</b></div></div>`;}
function brandmarkModal(){const emojis=['💰','📊','📁','🏛️','🎓','🌱','📚','🧾','💼','⭐','❤️','🏠'];modal('自訂品牌標記',`<div class="brandmark-editor"><p>選擇 Emoji，或上傳圖片作為左上角品牌標記。</p><div class="brandmark-emoji-grid">${emojis.map(x=>`<button type="button" class="brandmark-emoji" onclick="saveBrandmark({type:'emoji',value:'${x}'})">${x}</button>`).join('')}</div><div class="field brandmark-upload-field"><label for="brandmarkFile">上傳圖片（選填）</label><input id="brandmarkFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></div><button type="button" class="secondary brandmark-reset-button" onclick="saveBrandmark({type:'emoji',value:'經'})">還原預設標記</button><p class="hint">圖片會縮放後儲存在 SQLite，備份資料庫即可攜帶到其他電腦。</p></div>`,async()=>{},{hideSave:true});$('#brandmarkFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>5*1024*1024){toast('圖片需小於 5 MB');return}try{const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,256/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('圖片轉換失敗')),'image/png'));const data=await new Promise((resolve,reject)=>{const rd=new FileReader();rd.onload=()=>resolve(rd.result);rd.onerror=()=>reject(Error('讀取圖片失敗'));rd.readAsDataURL(blob)});await saveBrandmark({type:'image',value:data})}catch(err){toast(err.message||'圖片無法讀取')}}}

function customThemeModal(){const css=getComputedStyle(document.documentElement),saved=S.data?.settings?.custom_theme||{},base={canvas:css.getPropertyValue('--canvas').trim()||'#F4F1EC',paper:css.getPropertyValue('--paper').trim()||'#FFFFFF',table:css.getPropertyValue('--table-surface').trim()||'#FAF8F4',ink:css.getPropertyValue('--ink').trim()||'#1F2937',accent:css.getPropertyValue('--green').trim()||'#4B5563'},p=document.documentElement.dataset.theme==='custom'?{...base,...saved,table:saved.table||base.table}:base,labels={canvas:'頁面底色',paper:'面板底色',table:'表格底色',ink:'文字顏色',accent:'重點色'},inputs=()=>Object.entries(labels).map(([k,label])=>`<div class="field color-field"><label for="palette_${k}">${label}</label><input id="palette_${k}" type="color" value="${p[k]}" oninput="previewCustomTheme()"></div>`).join('');modal('自訂顏色',`<p class="hint">目前以「${$('#themeToggle').textContent}」的配色為基礎。面板與表格底色分開設定，其他顏色可維持不變。</p><form id="customThemeForm" class="formgrid">${inputs()}</form><div id="customThemePreview" class="custom-theme-preview"><div class="preview-surface"><b>面板預覽</b><p>文字與按鈕</p></div><div class="preview-table"><b>表格預覽</b><div>表格資料列</div></div><button type="button" class="preview-action">主要按鈕</button></div><p id="customThemeContrast" class="hint"></p><p class="hint">套用後會儲存在 SQLite；可隨時切換回其他主題。</p>`,async()=>{const palette=readCustomPalette();await api({op:'custom_theme_save',palette});S.data.settings.custom_theme=palette;setTheme('custom',false);closeModal(true);toast('自訂顏色已儲存')},{saveText:'儲存並套用'});previewCustomTheme()}

function validateBudgetImportRows(rows){const already=$('#importMode')?.value==='replace'?0:budgets().reduce((s,x)=>s+Number(x.initial||0),0),incoming=rows.reduce((s,x)=>s+Number(x.initial||0),0),sum=already+incoming,cap=Number(proj()?.total_budget||0);return sum>cap?[`匯入後預算明細合計 ${money(sum)} 元，超過專案總額 ${money(cap)} 元`]:[]};
function validateExpenseImportRows(rows){
 const errors=[],existing=expenses().filter(x=>!x.voided),items=budgets();
 let totalSpent=existing.reduce((s,x)=>s+Number(x.amount||0),0);
 const planLimit=Math.min(Number(proj()?.total_budget||0),items.reduce((s,x)=>s+Number(x.initial||0),0));
 const ownerSpent={},ownerLimit={},sourceSpent={},sourceLimit={},itemRoom={},itemReserved={};
 existing.forEach(x=>{ownerSpent[x.owner]=(ownerSpent[x.owner]||0)+Number(x.amount||0);sourceSpent[x.source]=(sourceSpent[x.source]||0)+Number(x.amount||0)});
 items.forEach(x=>{
  ownerLimit[x.owner]=(ownerLimit[x.owner]||0)+Number(x.budget||0);
  sourceLimit[x.source]=(sourceLimit[x.source]||0)+Number(x.initial||0);
  const key=JSON.stringify([x.source,x.owner,x.subject,x.category]);
  itemRoom[key]=Number(x.balance||0)-Number(x.reserved_out||0);
  itemReserved[key]=Number(x.reserved_out||0);
 });
 for(const [i,r] of rows.entries()){
  const amount=Number(r.amount||0),label=r._file&&r._row_number?`${r._file} 第 ${r._row_number} 列`:`第 ${i+1} 列`;
  if(!sources.includes(r.source)||!r.owner||!r.subject||!r.category)errors.push(`${label}經費類別、單位、經費屬性或預算科目無效`);
  const item=items.find(x=>x.source===r.source&&x.owner===r.owner&&x.subject===r.subject&&x.category===r.category);
  if(!item&&!r.missing_budget_item)errors.push(`${label}：找不到經費類別「${r.source}」、單位「${r.owner}」、預算科目「${r.subject}」、經費屬性「${r.category}」完全相符的預算明細`);
  if(r.payees?.length&&r.payees.reduce((s,x)=>s+Number(x.amount||0),0)!==amount)errors.push(`${label}付款分配合計與核銷金額不符`);
  totalSpent+=amount;ownerSpent[r.owner]=(ownerSpent[r.owner]||0)+amount;sourceSpent[r.source]=(sourceSpent[r.source]||0)+amount;
  if(totalSpent>planLimit)errors.push(`${label}會超過全專案核銷上限`);
  if(sourceSpent[r.source]>(sourceLimit[r.source]||0))errors.push(`${label}會超過經費類別「${r.source}」的核銷上限`);
  if(ownerSpent[r.owner]>(ownerLimit[r.owner]||0))errors.push(`${label}會超過單位「${r.owner}」的核銷上限`);
  if(item){const key=JSON.stringify([r.source,r.owner,r.subject,r.category]),room=itemRoom[key]||0;if(itemReserved[key]>0&&(room<0||amount>Math.max(0,room)))errors.push(`${label}會占用規劃流用圈存額度；此預算明細最多可核銷 ${money(Math.max(0,room))} 元`);itemRoom[key]=room-amount}
 }
 return [...new Set(errors)]
};

