function budgetModal(id){const b=id?budgets().find(x=>x.id==id):{};modal(id?'編輯預算':'新增預算',`<form id="budgetForm" class="formgrid">${hidden('id',b.id||'')}${hidden('project_id',S.project)}${selectField('經費類別','source',b.source||'',sources,true)}${selectField('單位','owner',b.owner||'',optList('owner'),true)}${selectField('經費屬性','category',b.category||'',optList('category'),true)}${selectField('預算科目','subject',b.subject||'',optList('subject'),true)}${field('初始預算','initial',b.initial??'',true,'number')}</form><p class="hint">同一經費類別、單位及預算科目可依不同經費屬性建立多筆預算。</p>`,async()=>{await api({op:'budget_save',data:formData('#budgetForm')});closeModal();await load();toast('預算已儲存')})}

function showTransferBudgetCreateConfirmation(items){return new Promise(resolve=>{const back=document.createElement('div');back.className='modal-back expense-budget-confirm-back';const list=items.map(x=>`<li>${esc(x.source)}／${esc(x.to_owner)}／${esc(x.to_category)}／${esc(x.to_subject)}</li>`).join('');back.innerHTML=`<section class="modal expense-budget-confirm" role="alertdialog" aria-modal="true" aria-labelledby="transferBudgetConfirmTitle" tabindex="-1"><div class="modal-head"><h2 id="transferBudgetConfirmTitle">建立流入預算明細？</h2></div><p>以下流入單位尚無相符的預算明細；確認後會以初始預算 <b>0 元</b> 建立${items.length>1?` ${items.length} 筆`:'一筆'}明細，再儲存流用資料：</p><div class="expense-budget-confirm-items"><ul>${list}</ul></div><div class="expense-budget-confirm-actions"><button type="button" class="ghost" data-confirm="cancel">返回</button><button type="button" class="primary" data-confirm="accept">確認建立並儲存</button></div></section>`;const finish=value=>{document.removeEventListener('keydown',onKey,true);back.remove();$('#saveModal')?.focus();resolve(value)};const onKey=e=>{if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();finish(false)}else if(e.key==='Tab'&&back.contains(e.target)){const controls=[...back.querySelectorAll('button:not(:disabled)')],first=controls[0],last=controls.at(-1);if(e.shiftKey&&e.target===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&e.target===last){e.preventDefault();first.focus()}}};back.querySelector('[data-confirm="cancel"]').addEventListener('click',()=>finish(false));back.querySelector('[data-confirm="accept"]').addEventListener('click',()=>finish(true));document.addEventListener('keydown',onKey,true);$('#modalRoot').append(back);back.querySelector('[data-confirm="cancel"]').focus()});if(!confirmed&&save){save.disabled=false;save.focus()}return confirmed}
function missingTransferTargets(rows){const existing=new Set(budgets().map(x=>JSON.stringify([x.source,x.owner,x.subject,x.category]))),items=new Map();for(const x of rows||[]){const key=JSON.stringify([x.source,x.to_owner,x.to_subject,x.to_category]);if(!existing.has(key))items.set(key,{source:x.source,to_owner:x.to_owner,to_subject:x.to_subject,to_category:x.to_category})}return [...items.values()]}
