function showTransferLimit(){
 const d=formData('#transferForm',false),old=d.id?transfers().find(t=>String(t.id)===String(d.id)):null;
 const x=budgets().find(x=>x.source===d.source&&x.owner===d.from_owner&&x.subject===d.from_subject&&x.category===d.from_category),el=$('#transferLimit');
 if(!el)return;
 const sourceComplete=!!(d.source&&d.from_owner&&d.from_subject&&d.from_category),amount=numericMoney(d.amount),isPlanned=d.status==='planned';
 if(!sourceComplete){el.textContent=isPlanned?'流出項目尚未填齊，目前不會圈存額度。':'請填妥流出預算明細，才能檢查可流用餘額。';return}
 if(!x){el.textContent='找不到完全相符的流出預算明細，無法圈存或執行流用。';return}
 const matches=side=>old&&old.source===x.source&&old[side+'_owner']===x.owner&&old[side+'_subject']===x.subject&&old[side+'_category']===x.category;
 const adjustment=old?.status==='executed'?Number(old.amount||0):0;
 const actual=Number(x.balance||0)+(matches('from')?adjustment:0)-(matches('to')?adjustment:0);
 const ownReservation=old?.status==='planned'&&matches('from')?Number(old.amount||0):0;
 const reservedOthers=Math.max(0,Number(x.reserved_out||0)-ownReservation),available=actual-reservedOthers;
 let unitBalance=budgets().filter(b=>b.owner===d.from_owner).reduce((sum,b)=>sum+Number(b.balance||0),0);
 if(old?.status==='executed'){if(old.from_owner===d.from_owner)unitBalance+=adjustment;if(old.to_owner===d.from_owner)unitBalance-=adjustment}
 const planned=transfers().filter(t=>t.status==='planned'&&t.from_owner===d.from_owner&&t.from_budget_item_id&&Number(t.amount)>0&&t.id!==old?.id);
 const ownerReserved=planned.filter(t=>t.to_owner!==t.from_owner).reduce((sum,t)=>sum+Number(t.amount||0),0),unitRoom=unitBalance-ownerReserved;
 const group=budgets().filter(b=>b.owner===d.from_owner&&b.source===d.source&&b.category===d.from_category);
 let groupBalance=group.reduce((sum,b)=>sum+Number(b.balance||0),0);
 if(old?.status==='executed'){if(old.source===d.source&&old.from_owner===d.from_owner&&old.from_category===d.from_category)groupBalance+=adjustment;if(old.source===d.source&&old.to_owner===d.from_owner&&old.to_category===d.from_category)groupBalance-=adjustment}
 const reservations=planned.filter(t=>t.source===d.source&&t.from_category===d.from_category),groupReserved=reservations.reduce((sum,t)=>sum+Number(t.amount||0),0),groupRoom=groupBalance-groupReserved;
 const crossUnit=d.from_owner!==d.to_owner,limits=[{kind:'detail',value:available}];
 if(isPlanned||crossUnit)limits.push({kind:'group',value:groupRoom});
 if(crossUnit)limits.push({kind:'unit',value:unitRoom});
 const limiting=limits.reduce((best,entry)=>entry.value<best.value?entry:best),max=Math.max(0,limiting.value),verb=isPlanned?'圈存':'流出';
 const groupName=`${d.from_owner}／${d.source}／${d.from_category}`;
 const reason=limiting.kind==='group'?`${groupName} 組合剩餘 ${money(groupRoom)} 元${groupReserved?`（已扣規劃圈存 ${money(groupReserved)} 元）`:''}`:limiting.kind==='unit'?`流出後單位總經費剩餘 ${money(unitRoom)} 元${ownerReserved?`（已扣跨單位規劃圈存 ${money(ownerReserved)} 元）`:''}`:`此預算明細實際餘額 ${money(actual)} 元${reservedOthers?`，其中規劃圈存 ${money(reservedOthers)} 元`:''}`;
 const detail=reservations.length?` 圈存明細：${reservations.map(t=>`#${t.id} ${t.from_subject} → ${t.to_owner&&t.to_subject?`${t.to_owner}／${t.to_subject}`:'流入尚未指定'}`).join('；')}。如需動用，請先調整或刪除該規劃流用。`:'';
 el.textContent=`${reason}，本筆最多可${verb} ${money(max)} 元。${detail}${old?.status==='executed'&&matches('from')?'（已加回本筆原流出並重新計算）':''}${amount>max?`目前金額超過可${verb}額度。`:''}`;
}
